// Localizes activity summaries generated by the backend (services/*.py log_event calls).
// User/agent-written text (progress notes) is never translated — only these system templates.
import { getLang, t } from "./index";

const LABEL_BY_ENUM: Record<string, string> = {
  ideation: "Ideation", research_design: "Research Design", implementation: "Implementation",
  experimentation: "Experimentation", analysis: "Analysis", writing: "Writing", submission: "Submission",
  revision: "Revision", completed: "Completed", on_hold: "On Hold", on_track: "On Track", at_risk: "At Risk",
  blocked: "Blocked", todo: "Todo", in_progress: "In Progress", done: "Done", cancelled: "Cancelled",
  planned: "Planned", running: "Running", analyzing: "Analyzing", needs_review: "Needs Review",
  verified: "Verified", failed: "Failed",
};

/** Translate an enum value or an English label ("Analysis") into the current language. */
const L = (v: string) => t(LABEL_BY_ENUM[v.trim()] ?? v.trim());

const FIELD: Record<string, string> = {
  title: "标题", slug: "短标识", description: "描述", research_question: "研究问题", hypothesis: "假设",
  target_venue: "目标会议/期刊", submission_deadline: "投稿截止日期", priority: "优先级", repository_url: "仓库地址",
  next_action: "下一步行动", blocker_summary: "阻塞", links: "链接", due_date: "截止日期", milestone_id: "里程碑",
  project_id: "项目", tags: "标签", git_reference: "Git 引用", notes: "笔记", group_name: "分组", name: "名称",
  type: "类型", baseline: "基线", variant: "变体", conclusion: "结论", metrics_json: "指标", config_json: "配置",
  git_commit: "提交", git_branch: "分支", environment: "环境", artifact_links: "产物链接", seed: "种子",
  verification_status: "验证状态", status: "状态", started_at: "开始时间", finished_at: "结束时间",
};
const fields = (s: string) => s.split(",").map((f) => FIELD[f.trim()] ?? f.trim()).join("、");

type Rule = [RegExp, (...m: string[]) => string];

const ZH_RULES: Rule[] = [
  [/^Project created: (.*)$/s, (x) => `创建项目：${x}`],
  [/^Stage changed: (.*) → (.*)$/, (a, b) => `阶段变更：${L(a)} → ${L(b)}`],
  [/^Health changed: (.*) → (.*)$/, (a, b) => `健康度变更：${L(a)} → ${L(b)}`],
  [/^Project archived$/, () => "项目已归档"],
  [/^Project restored$/, () => "项目已恢复"],
  [/^Project updated: (.*)$/, (f) => `项目已更新：${fields(f)}`],
  [/^Milestone added: (.*)$/s, (x) => `添加里程碑：${x}`],
  [/^Milestone completed: (.*)$/s, (x) => `完成里程碑：${x}`],
  [/^Milestone deleted: (.*)$/s, (x) => `删除里程碑：${x}`],
  [/^Milestone '(.*)' updated: (.*)$/s, (x, f) => `里程碑“${x}”已更新：${fields(f)}`],
  [/^Milestone '(.*)': (\w+) → (\w+)$/s, (x, a, b) => `里程碑“${x}”：${L(a)} → ${L(b)}`],
  [/^Task created: (.*)$/s, (x) => `创建任务：${x}`],
  [/^Task completed: (.*)$/s, (x) => `完成任务：${x}`],
  [/^Task deleted: (.*)$/s, (x) => `删除任务：${x}`],
  [/^Task '(.*)' updated: (.*)$/s, (x, f) => `任务“${x}”已更新：${fields(f)}`],
  [/^Task '(.*)': (\w+) → (\w+)$/s, (x, a, b) => `任务“${x}”：${L(a)} → ${L(b)}`],
  [/^Experiment recorded: (.*?)(?: \((.*)\))?$/s, (x, g) => `记录实验：${x}${g ? `（${g}）` : ""}`],
  [/^Experiment deleted: (.*)$/s, (x) => `删除实验：${x}`],
  [/^Experiment '(.*)' updated: (.*)$/s, (x, f) => `实验“${x}”已更新：${fields(f)}`],
  [/^Experiment '(.*)': (\w+) → (\w+)$/s, (x, a, b) => `实验“${x}”：${L(a)} → ${L(b)}`],
  [/^Run (\S+) recorded for '(.*)'(?: \(seed (-?\d+)\))?(?:: (.*))?$/s,
    (r, x, seed, m) => `记录运行 ${r}（实验“${x}”${seed !== undefined ? `，种子 ${seed}` : ""}）${m ? `：${m}` : ""}`],
  [/^Run (\S+) of '(.*)' verified$/s, (r, x) => `运行 ${r}（实验“${x}”）已验证`],
  [/^Run (\S+) of '(.*)' deleted$/s, (r, x) => `运行 ${r}（实验“${x}”）已删除`],
  [/^Run (\S+) of '(.*)' updated: (.*)$/s, (r, x, f) => `运行 ${r}（实验“${x}”）已更新：${fields(f)}`],
];

export function localizeSummary(summary: string, eventType: string): string {
  if (getLang() !== "zh" || eventType === "progress_note") return summary;
  for (const [re, fn] of ZH_RULES) {
    const m = summary.match(re);
    if (m) return fn(...m.slice(1));
  }
  return summary;
}
